# Jana www/data/mathurat.js — Al-Ma'thurat Sughra.
# Ayat Al-Quran diambil terus daripada teks Al-Quran Wazlee yang telah disahkan (www/quran/s/*.json).
# Susunan & bilangan rujuk versi Sughra lazim di Malaysia (rujukan: github.com/adiman-dev/Mathurat), teks zikir disemak & dibetulkan.
import json, os
Q = lambda n: json.load(open(f'www/quran/s/{n:03d}.json'))
def quran(name, nameEn, s, a1, a2, n=1, bism=False):
    d = Q(s); idx = range(a1 - 1, a2)
    AR = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
    a = ' '.join(f'{d["a"][i]} ﴿{str(i+1).translate(AR)}﴾' for i in idx)
    if bism: a = Q(1)['a'][0] + '\n' + a
    return dict(t=name, te=nameEn, q=f'{s}:{a1}-{a2}', n=n, w='both', a=a,
                r='', m=' '.join(f'({i+1}) {d["ms"][i]}' for i in idx), me=' '.join(f'({i+1}) {d["en"][i]}' for i in idx))
def z(t, te, n, w, a, r, m, me): return dict(t=t, te=te, n=n, w=w, a=a, r=r, m=m, me=me)
